using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace TheTrailWalker.Editor
{
    // Settlement route art (regions 3-4 spec, November 8, 2026): entrance arch, palisade segment and split-rail fence,
    // generated by Tools/Art/generate_settlement_arch.py. Build makes the prefabs; Validate checks the opening and budgets;
    // CapturePreview renders a review sheet to Docs/Art/Settlement/Route.
    public static class SettlementArchAssets
    {
        const string Source = "Assets/_Game/Art/Settlement/Route/";
        const string Target = "Assets/_Game/Resources/Settlement/Route/";
        const string Docs = "Docs/Art/Settlement/Route/";
        public static readonly string[] Parts = { "EntranceArch", "PalisadeSegment", "FenceSection" };
        public const int TriangleBudget = 900;
        public const float RoadWidth = 3.4f, MinimumClearWidth = 4.2f, MinimumClearHeight = 3.2f;

        [MenuItem("The Trail Walker/Art/Build Settlement Route")]
        public static void Build()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode) throw new InvalidOperationException("Build outside Play mode.");
            AssetDatabase.Refresh();
            string palette = Source + "SettlementRoutePalette.png";
            var texture = (TextureImporter)AssetImporter.GetAtPath(palette);
            texture.filterMode = FilterMode.Point; texture.mipmapEnabled = false; texture.wrapMode = TextureWrapMode.Clamp; texture.alphaSource = TextureImporterAlphaSource.FromInput;
            texture.alphaIsTransparency = false; texture.textureCompression = TextureImporterCompression.Uncompressed; texture.npotScale = TextureImporterNPOTScale.None; texture.SaveAndReimport();
            Directory.CreateDirectory(Target);
            var material = AssetDatabase.LoadAssetAtPath<Material>(Target + "SettlementRoutePalette.mat");
            if (material == null) { material = new Material(Shader.Find(FacetedDetailMaterials.ShaderName)); AssetDatabase.CreateAsset(material, Target + "SettlementRoutePalette.mat"); }
            FacetedDetailMaterials.Configure(material, AssetDatabase.LoadAssetAtPath<Texture2D>(palette));
            foreach (string name in Parts)
            {
                var importer = (ModelImporter)AssetImporter.GetAtPath(Source + name + ".obj");
                importer.globalScale = 1; importer.importAnimation = false; importer.importCameras = false; importer.importLights = false; importer.addCollider = false;
                importer.materialImportMode = ModelImporterMaterialImportMode.None; importer.isReadable = true;   // combined at runtime on device
                importer.importNormals = ModelImporterNormals.Calculate; importer.normalSmoothingAngle = 0; importer.SaveAndReimport();
                var root = new GameObject(name);
                try
                {
                    var part = UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Source + name + ".obj"), root.transform, false); part.name = name + "Mesh";
                    foreach (var renderer in part.GetComponentsInChildren<MeshRenderer>()) renderer.sharedMaterial = material;
                    PrefabUtility.SaveAsPrefabAsset(root, Target + name + ".prefab");
                }
                finally { UnityEngine.Object.DestroyImmediate(root); }
            }
            AssetDatabase.SaveAssets();
        }

        static Mesh MeshOf(GameObject prefab) => prefab.GetComponentInChildren<MeshFilter>()?.sharedMesh;

        public static void Validate(Action<bool, string> check)
        {
            foreach (string name in Parts)
            {
                var prefab = Resources.Load<GameObject>("Settlement/Route/" + name);
                Mesh mesh = prefab == null ? null : MeshOf(prefab);
                var renderer = prefab == null ? null : prefab.GetComponentInChildren<MeshRenderer>();
                check(mesh != null && renderer != null, $"{name} prefab exists with a mesh");
                check(mesh.triangles.Length / 3 <= TriangleBudget, $"{name} stays within {TriangleBudget} triangles ({mesh.triangles.Length / 3})");
                check(renderer.sharedMaterial != null && renderer.sharedMaterial.shader.name == FacetedDetailMaterials.ShaderName && renderer.sharedMaterial.GetTexture("_BaseMap") != null,
                    $"{name} uses the route palette with the faceted detail shader");
            }
            // Points spread over every triangle (a log post has vertices only at its ends, so vertices alone miss its sides).
            Mesh archMesh = MeshOf(Resources.Load<GameObject>("Settlement/Route/EntranceArch"));
            Vector3[] v = archMesh.vertices; int[] t = archMesh.triangles;
            var arch = new System.Collections.Generic.List<Vector3>();
            for (int i = 0; i < t.Length; i += 3)
                for (int a = 0; a <= 8; a++) for (int b = 0; a + b <= 8; b++)
                    arch.Add(v[t[i]] + (v[t[i + 1]] - v[t[i]]) * (a / 8f) + (v[t[i + 2]] - v[t[i]]) * (b / 8f));
            // Clear opening: nothing between the posts below the minimum height (stone footings at ground level aside),
            // and nothing over the opening below the hanging board.
            float halfWidth = arch.Where(p => p.y > 0.25f && p.y < MinimumClearHeight).Select(p => Mathf.Abs(p.x)).DefaultIfEmpty(0f).Min();
            float clearHeight = arch.Where(p => Mathf.Abs(p.x) < MinimumClearWidth / 2f && p.y > 0.3f).Select(p => p.y).DefaultIfEmpty(0f).Min();
            check(halfWidth * 2f >= MinimumClearWidth && MinimumClearWidth > RoadWidth, $"The arch opening is at least {MinimumClearWidth} m wide (road {RoadWidth} m): {halfWidth * 2f:0.00} m");
            check(clearHeight >= MinimumClearHeight, $"The arch opening is at least {MinimumClearHeight} m high: {clearHeight:0.00} m");
        }

        [MenuItem("The Trail Walker/Art/Capture Settlement Route")]
        public static void CapturePreview()
        {
            Directory.CreateDirectory(Docs);
            var preview = new PreviewRenderUtility();
            Material groundMaterial = null;
            try
            {
                // Review layout: the road through the arch, palisade either side, fences along the approach.
                void Add(string name, Vector3 position, float yaw) { var view = UnityEngine.Object.Instantiate(Resources.Load<GameObject>("Settlement/Route/" + name)); view.transform.SetPositionAndRotation(position, Quaternion.Euler(0, yaw, 0)); preview.AddSingleGO(view); }
                Add("EntranceArch", Vector3.zero, 0);
                for (int i = 0; i < 4; i++) { Add("PalisadeSegment", new Vector3(5.2f + i * 4f, 0, 0), 0); Add("PalisadeSegment", new Vector3(-5.2f - i * 4f, 0, 0), 0); }
                for (int i = 0; i < 4; i++) { Add("FenceSection", new Vector3(4.5f, 0, -6f - i * 4f), 90); Add("FenceSection", new Vector3(-4.5f, 0, -6f - i * 4f), 90); }
                var ground = GameObject.CreatePrimitive(PrimitiveType.Cube); UnityEngine.Object.DestroyImmediate(ground.GetComponent<Collider>());
                ground.transform.position = new Vector3(0, -0.05f, -8); ground.transform.localScale = new Vector3(40, 0.1f, 30);
                groundMaterial = new Material(Shader.Find("Universal Render Pipeline/Lit")); groundMaterial.SetColor("_BaseColor", new Color(.36f, .45f, .26f)); ground.GetComponent<Renderer>().sharedMaterial = groundMaterial;
                preview.AddSingleGO(ground);
                var road = GameObject.CreatePrimitive(PrimitiveType.Cube); UnityEngine.Object.DestroyImmediate(road.GetComponent<Collider>());
                road.transform.position = new Vector3(0, 0.0f, -10); road.transform.localScale = new Vector3(RoadWidth, 0.02f, 24);
                var roadMaterial = new Material(groundMaterial); roadMaterial.SetColor("_BaseColor", new Color(.55f, .45f, .32f)); road.GetComponent<Renderer>().sharedMaterial = roadMaterial;
                preview.AddSingleGO(road);
                preview.camera.fieldOfView = 45; preview.camera.transform.position = new Vector3(3.5f, 2.6f, -16f); preview.camera.transform.LookAt(new Vector3(0, 2.4f, 0));
                preview.camera.clearFlags = CameraClearFlags.SolidColor; preview.camera.backgroundColor = new Color(.44f, .64f, .7f);
                preview.camera.nearClipPlane = .05f; preview.camera.farClipPlane = 120;
                preview.lights[0].intensity = 1.4f; preview.lights[0].transform.rotation = Quaternion.Euler(40, 150, 0); preview.lights[1].intensity = .6f;
                preview.ambientColor = new Color(.5f, .5f, .5f);
                preview.BeginStaticPreview(new Rect(0, 0, 1400, 900)); preview.Render(true); var image = preview.EndStaticPreview();
                try { File.WriteAllBytes(Docs + "settlement-route-review.png", image.EncodeToPNG()); } finally { UnityEngine.Object.DestroyImmediate(image); UnityEngine.Object.DestroyImmediate(roadMaterial); }
            }
            finally { preview.Cleanup(); if (groundMaterial != null) UnityEngine.Object.DestroyImmediate(groundMaterial); }
        }
    }
}
